        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        emon.Testport.assertEq(Inflate.izZlib(emon.Testport.hexBlob("7801 cb48cdc9c9"), 0, 7, out, st), Inflate.izTruncated(), "truncated");
